CREATE VIRTUAL TABLE agent_playbooks_vec USING vec0(
                embedding float[512]
            )

CREATE VIRTUAL TABLE interactions_vec USING vec0(
                embedding float[512]
            )

CREATE VIRTUAL TABLE playbook_aggregation_clusters_vec USING vec0(
                embedding float[512] distance_metric=cosine
            )

CREATE VIRTUAL TABLE profiles_vec USING vec0(
                embedding float[512]
            )

CREATE VIRTUAL TABLE user_playbooks_vec USING vec0(
                embedding float[512]
            )

CREATE TRIGGER agent_playbooks_unicode_fts_au
AFTER UPDATE OF trigger, content, rationale ON agent_playbooks BEGIN
    DELETE FROM agent_playbooks_unicode_fts WHERE rowid = old.rowid;
    INSERT INTO agent_playbooks_unicode_fts(rowid, search_ngrams)
    VALUES (
        new.rowid,
        reflexio_unicode_lexical_index(
            COALESCE(new.trigger, '') || ' ' ||
            COALESCE(new.content, '') || ' ' ||
            COALESCE(new.rationale, '')
        )
    );
END

CREATE TRIGGER capture_playbook_aggregation_hard_delete
BEFORE DELETE ON user_playbooks
WHEN OLD.status IS NULL AND trim(OLD.agent_version) <> ''
BEGIN
    INSERT INTO playbook_aggregation_invalidation(
        agent_version, operation, entity_id, source_ids
    ) VALUES (OLD.agent_version, 'hard_delete', OLD.user_playbook_id, '[]');
    INSERT INTO playbook_aggregation_state(
        agent_version, pending, next_attempt_at
    ) VALUES (OLD.agent_version, 1, unixepoch())
    ON CONFLICT(agent_version) DO UPDATE SET pending=1;
END

